head.script:
// https://inswave01.atlassian.net/browse/WAEA-913



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setAutoFit]<br/>GridView 컴포넌트에 AutoFit 기능을 설정합니다.",
    "validation" : [
        "options(필수) 파라미터로 GridView 너비에 맞게 각 Column 너비가 자동 조정되는 방식을 설정합니다.",
        "options.type(필수) 파라미터로 autoFit 적용 방식을 대소문자를 구분하여 정확히 설정합니다.",
        "type 'allColumn' : 각 Column 너비 비율 유지하며 조정하여 컴포넌트에 한번에 표시합니다.",
        "type 'lastColumn' : 마지막 Column 너비만 조정하여 여백을 채워 모두 표시합니다.",
        "설정한 파라미터값이 autoFit 속성에 무조건 설정됩니다.",
        "options.minWidth(선택) 파라미터로 AutoFit 적용 방식이 변경되는 최소 너비를 px 로 설정합니다. type 이 'lastColumn' 이면 적용되지 않으며 생략하면 autoFitMinWidth 속성값이 적용됩니다.",
        "GridView 너비가 minWidth 파라미터값보다 크면 GridView 너비에 맞게 AutoFit 이 적용됩니다.",
        "GridView 너비가 minWidth 파라미터값보다 작으면 내부 너비가 파라미터값만큼 확장된 후 가로 스크롤바가 표시되고 내부 너비에 맞게 AutoFit 이 적용됩니다.",
        "type 이 'lastColumn' 일때 GridView 에 가로 스크롤이 표시되어 있으면 Column 너비가 자동 조정되지 않습니다.",
        "AutoFit 기능이 설정되면 Column 또는 GridView 의 너비가 변경될때 설정값에 맞게 자동으로 Column 너비가 재조정됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - Method 샘플이므로 con_ 옵션은 없음. autoFit 속성 미설정 상태로 그리드만 생성하고
//    par_ 파라미터 UI 로 setAutoFit() 을 호출하여 AutoFit 을 설정한다.
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // dataList 바인딩 (autoFit 속성 미설정 — setAutoFit 으로 설정)
    let properties = {
        dataList: "data:dlt_bind",
    };

    let cList = $c.gcm.createCList(properties);

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    //  - GridView 너비 500px, 각 Column 기본 70px(합 280px) 이므로 여백이 발생하여 AutoFit 효과를 시각적으로 확인 가능
    $c.gcm.createLabel('label="[전제] GridView 500px / Column 4개(여백). type·minWidth 선택 후 setAutoFit 실행. minWidth 큰값이면 내부 확장+가로 스크롤 / 작은값이면 너비 맞춤."', '', 'label1');

    // dataList 생성 (4행)
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // target 생성 (autoFit 속성 미설정)
    await $c.gcm.createBasicGridView(cList, '');
}



// setAutoFit(options) 호출
//  - par_type   : '' 미설정(필수 미충족 케이스, '' 그대로 전달) / 'allColumn' / 'lastColumn'
//  - par_minWidth : '' 미설정(키 미포함, autoFitMinWidth 속성 기본값 경로) / '300'(작은값) / '800'(큰값)
scwin.btn_setAutoFit_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");

    let vType = par_type.getValue();
    let vMinWidth = par_minWidth.getValue();

    // type 은 필수 파라미터이므로 빈값이어도 '' 로 항상 전달(필수 미충족 의도 명확화)
    let options = {};
    options.type = vType;

    // minWidth : 미설정('') 이면 키 미포함 / 그 외는 Number 변환
    if (vMinWidth !== '') {
        options.minWidth = Number(vMinWidth);
    }

    target1.setAutoFit(options);

    bottom.btn_clear_onclick();
    bottom.setReturnValue("setAutoFit(" + JSON.stringify(options) + ") 호출 → [너비/스크롤 확인] 버튼으로 결과 확인");
}



// AutoFit 적용 결과 확인
//  - autoFit 속성(설정값이 무조건 설정됨) / 각 Column 너비 / 내부 너비 / 가로 스크롤 발생 여부
//  - allColumn/lastColumn, minWidth 큰값(800 → 가로스크롤)/작은값(300), lastColumn+가로스크롤(@spec1) 확인
scwin.btn_checkWidth_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    bottom.setReturnValue("[옵션] autoFit : " + target1.options.autoFit);

    // 각 Column 의 실제 너비 (헤더 th id 는 1부터, Column 인덱스는 0 부터, 숨김 제외)
    let widths = [];
    let totalWidth = 0;
    for (var i = 0; i < 4; i++) {
        let th = document.querySelector("th[id*='target1_column" + (i + 1) + "']");
        if (th && target1.getColumnVisible(i)) {
            widths.push("Column(" + i + ") : " + th.offsetWidth + "px");
            totalWidth += th.offsetWidth;
        }
    }
    bottom.setReturnValue(widths.join(" / "));

    // GridView 내부 body 테이블 너비 + 가로 스크롤바 표시 여부 (엔진은 _scrollX_div 영역 높이로 판단)
    let bodyTable = document.querySelector("[id*='target1_body_table']");
    let innerWidth = bodyTable ? bodyTable.offsetWidth : 0;
    let scrollXDiv = document.querySelector("[id*='target1_scrollX_div']");
    let hasXScroll = scrollXDiv ? (scrollXDiv.offsetHeight > 0) : false;

    bottom.setReturnValue("Column 너비 합 : " + totalWidth + "px / GridView 내부 너비 : " + innerWidth + "px / 가로 스크롤바 발생 : " + hasXScroll);
}
